"use client";

import { useState } from "react";
import { useTranslations } from "next-intl";
import { api } from "@/lib/api";
import { toast } from "sonner";
import { Loader2, UserPlus } from "lucide-react";
import { useRouter } from "@/i18n/routing";

export default function RegisterPage() {
  const t = useTranslations();
  const router = useRouter();
  const [username, setUsername] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (password !== confirmPassword) {
      toast.error(t('auth.passwordMismatch') || "两次密码输入不一致");
      return;
    }
    setIsLoading(true);
    try {
      await api.post("/api/auth/register", { username, email, password });
      toast.success(t('auth.registerSuccess') || "注册成功");
      router.push("/login");
    } catch (err: unknown) {
      const error = err as { response?: { data?: { detail?: string } } };
      toast.error(error.response?.data?.detail || t('auth.registerFailed') || "注册失败");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4 bg-paper">
      <div className="w-full max-w-sm bg-white rounded-2xl shadow-lg p-6">
        <h1 className="text-xl font-bold text-dark text-center mb-6">
          AI Career Co-pilot
        </h1>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="text-sm text-text-secondary mb-1 block">用户名</label>
            <input
              type="text"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="w-full px-3 py-2 border border-border-subtle rounded-lg text-sm"
              required
            />
          </div>
          <div>
            <label className="text-sm text-text-secondary mb-1 block">邮箱</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full px-3 py-2 border border-border-subtle rounded-lg text-sm"
              required
            />
          </div>
          <div>
            <label className="text-sm text-text-secondary mb-1 block">密码</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-3 py-2 border border-border-subtle rounded-lg text-sm"
              required
            />
          </div>
          <div>
            <label className="text-sm text-text-secondary mb-1 block">确认密码</label>
            <input
              type="password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              className="w-full px-3 py-2 border border-border-subtle rounded-lg text-sm"
              required
            />
          </div>
          <button
            type="submit"
            disabled={isLoading}
            className="w-full py-2.5 bg-terra text-paper rounded-lg font-medium text-sm disabled:opacity-50"
          >
            {isLoading ? <Loader2 className="h-4 w-4 animate-spin mx-auto" /> : <><UserPlus className="h-4 w-4 inline mr-1" />注册</>}
          </button>
        </form>
        <p className="text-sm text-text-secondary text-center mt-4">
          已有账号？<a href="/login" className="text-terra font-medium">去登录</a>
        </p>
      </div>
    </div>
  );
}
